import type { PicPage, PicScene } from "./picture-books";

/**
 * Older stories retold as 16-page picture books for Book Mode. The story
 * page keeps the full original text; these short pages are what Book Mode
 * shows, one full illustration each, with a Baby Mo pose matched to the
 * moment. Added in batches.
 */
export interface AdaptedBook {
  cover: PicScene;
  pages: PicPage[];
}

const T = (id: string, en: string) => ({ id, en });

